def transform(grid):
    h, w = len(grid), len(grid[0])

    # Extract the ordered colors from the repeated three-row strip.
    palette = []
    for r in range(h - 2):
        if grid[r] == grid[r + 1] == grid[r + 2] and any(grid[r]):
            palette = [v for v in grid[r] if v != 0]
            break

    # The template is the connected color-1 component with the most cells.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            comp = []
            while todo:
                x, y = todo.pop()
                comp.append((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and (nx,ny) not in seen:
                        seen.add((nx, ny))
                        todo.append((nx, ny))
            components.append(comp)

    template = max(components, key=len)
    top = min(r for r, c in template)
    left = min(c for r, c in template)
    bottom = max(r for r, c in template)
    height = bottom - top + 1
    shape = [(r-top, c-left) for r, c in template]

    out = [[0] * w for _ in range(h)]
    first_top = top - palette.index(1) * height
    for i, color in enumerate(palette):
        for dr, dc in shape:
            rr, cc = first_top + i*height + dr, left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
